<?php use Camagru\Http\Http;
$headings = ['login' => 'Good to see you.', 'register' => 'A little more you.', 'forgot' => 'A fresh start.', 'resend' => 'One more little step.', 'verify' => 'Make it official.', 'reset' => 'Your fresh start.'];
$descriptions = ['login' => 'Your next favorite moment is waiting.', 'register' => 'Make something ordinary a little extraordinary.', 'forgot' => 'We’ll send you a link to reset your password.', 'resend' => 'We’ll send a new confirmation link to your inbox.', 'verify' => 'Confirm your email to finish this step.', 'reset' => 'Choose a new password for your account.']; ?>
<section class="account-shell"><div class="account-art" aria-hidden="true"><span class="art-label">THE EVERYDAY, REMIXED.</span><div class="abstract-camera"><div class="camera-lens">✳</div><div class="camera-flash"></div></div><p>There’s a little<br>magic in <em>every day.</em></p><span class="art-spark">✴</span></div>
<div class="account-panel"><span class="eyebrow">YOUR LITTLE CREATIVE CORNER</span><h1><?= Http::escape($headings[$mode]) ?></h1><p class="muted"><?= Http::escape($descriptions[$mode]) ?></p>
<form method="post" action="/<?= Http::escape($mode) ?>" class="stack-form">
    <?php if ($mode === 'login' && !empty($loginError)): ?><div class="login-error" id="login-error" role="alert"><p><?= Http::escape($loginError['message']) ?></p><a href="/forgot">Reset your password</a> or <a href="/resend">resend your confirmation email</a>.</div><?php endif; ?>
    <input type="hidden" name="csrf" value="<?= Http::escape($_SESSION['csrf']) ?>">
    <?php if ($mode === 'reset'): ?><input type="text" hidden name="username" autocomplete="username"><?php endif; ?>
    <?php if (in_array($mode,['register','login'],true)): ?><label>Username<input name="username" required minlength="3" maxlength="30" autocomplete="username" pattern="[A-Za-z0-9_]{3,30}" placeholder="Your creative alias" value="<?= Http::escape($mode === 'login' ? ($loginError['username'] ?? '') : '') ?>" <?= !empty($loginError) ? 'aria-describedby="login-error"' : '' ?>></label><?php endif; ?>
    <?php if (in_array($mode,['register','forgot','resend'],true)): ?><label>Email address<input type="email" name="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"></label><?php endif; ?>
    <?php if (in_array($mode,['register','login','reset'],true)): ?><label>Password<input type="password" name="password" required <?= $mode !== 'login' ? 'minlength="15" maxlength="128"' : '' ?> autocomplete="<?= $mode === 'login' ? 'current-password' : 'new-password' ?>"></label><?php endif; ?>
    <?php if (in_array($mode,['register','reset'],true)): ?><p class="field-help">15–128 characters, with at least a letter and a number.</p><label>Confirm password<input type="password" name="confirmation" required minlength="15" maxlength="128" autocomplete="new-password"></label><?php endif; ?>
    <?php if (in_array($mode,['verify','reset'],true)): ?><input type="hidden" name="token" value="<?= Http::escape($token) ?>"><?php endif; ?>
    <?php if ($mode === 'verify'): ?><input type="hidden" name="purpose" value="<?= Http::escape($purpose) ?>"><?php endif; ?>
    <button class="button" type="submit"><?= Http::escape(match ($mode) { 'register' => 'Create your account', 'login' => 'Sign in', 'forgot','resend' => 'Send me a link', 'verify' => 'Confirm email', 'reset' => 'Save new password' }) ?> <span aria-hidden="true">↗</span></button>
</form>
<?php if ($mode === 'login'): ?><p class="account-links"><a href="/forgot">Forgot password?</a><a href="/resend">Resend confirmation</a></p><p class="muted">New around here? <a href="/register">Make yourself at home.</a></p><?php else: ?><p class="muted">Already have an account? <a href="/login">Sign in.</a></p><?php endif; ?>
</div></section>
